#include "vm.h"
#include <cmath>
#include <iostream>
#include <sstream>
#include <stdexcept>
void VM::load(std::vector<Instruction>c){program=std::move(c);}Value VM::pop(){if(stack.empty())throw std::runtime_error("VM stack underflow");auto v=stack.back();stack.pop_back();return v;}bool VM::truthy(const Value&v){if(std::holds_alternative<bool>(v))return std::get<bool>(v);if(std::holds_alternative<std::monostate>(v))return false;if(std::holds_alternative<long long>(v))return std::get<long long>(v)!=0;if(std::holds_alternative<double>(v))return std::get<double>(v)!=0.0;return!std::get<std::string>(v).empty();}std::string VM::display(const Value&v){if(std::holds_alternative<std::monostate>(v))return"none";if(std::holds_alternative<long long>(v))return std::to_string(std::get<long long>(v));if(std::holds_alternative<double>(v)){std::ostringstream s;s<<std::get<double>(v);return s.str();}if(std::holds_alternative<bool>(v))return std::get<bool>(v)?"true":"false";return std::get<std::string>(v);}
int VM::run(){try{for(std::size_t ip=0;ip<program.size();++ip){const auto&i=program[ip];if(i.op=="HALT")return 0;if(i.op=="CONST")stack.emplace_back(i.arg.find('.')!=std::string::npos?Value(std::stod(i.arg)):Value(std::stoll(i.arg)));else if(i.op=="CONST_STR")stack.emplace_back(i.arg);else if(i.op=="CONST_BOOL")stack.emplace_back(i.arg=="true");else if(i.op=="CONST_NONE")stack.emplace_back(std::monostate{});else if(i.op=="LOAD")stack.push_back(variables.at(i.arg));else if(i.op=="STORE")variables[i.arg]=pop();else if(i.op=="PRINT")std::cout<<display(pop())<<"\n";else if(i.op=="NEG"){auto a=pop();if(std::holds_alternative<long long>(a))stack.emplace_back(-std::get<long long>(a));else stack.emplace_back(-std::get<double>(a));}else if(i.op=="NOT")stack.emplace_back(!truthy(pop()));else if(i.op=="ADD"||i.op=="SUB"||i.op=="MUL"||i.op=="DIV"||i.op=="MOD"){auto b=pop(),a=pop();if(i.op=="ADD"&&std::holds_alternative<std::string>(a)&&std::holds_alternative<std::string>(b)){stack.emplace_back(std::get<std::string>(a)+std::get<std::string>(b));continue;}double av=std::holds_alternative<long long>(a)?std::get<long long>(a):std::get<double>(a),bv=std::holds_alternative<long long>(b)?std::get<long long>(b):std::get<double>(b);if((i.op=="DIV"||i.op=="MOD")&&bv==0)throw std::runtime_error("division by zero");if(i.op=="ADD")stack.emplace_back(av+bv);else if(i.op=="SUB")stack.emplace_back(av-bv);else if(i.op=="MUL")stack.emplace_back(av*bv);else if(i.op=="DIV")stack.emplace_back(av/bv);else stack.emplace_back(std::fmod(av,bv));}else if(i.op=="EQ"||i.op=="NE"||i.op=="LT"||i.op=="GT"||i.op=="LE"||i.op=="GE"){auto b=pop(),a=pop();double av=std::holds_alternative<long long>(a)?std::get<long long>(a):std::get<double>(a),bv=std::holds_alternative<long long>(b)?std::get<long long>(b):std::get<double>(b);bool r=i.op=="EQ"?display(a)==display(b):i.op=="NE"?display(a)!=display(b):i.op=="LT"?av<bv:i.op=="GT"?av>bv:i.op=="LE"?av<=bv:av>=bv;stack.emplace_back(r);}else throw std::runtime_error("Unknown VM instruction: "+i.op);}return 0;}catch(const std::exception&e){std::cerr<<"Ask runtime error: "<<e.what()<<"\n";return 2;}}